VALUES (1910000000000005104, 1, 'CRM', 'OPPORTUNITY', '高金额商机自动发起流程',
        '新增商机且预计金额大于 50000 元时自动发起已配置流程', 'EVENT', 'RECORD_CREATED_START_FLOW', 'ASYNC', 0,
        'RECORD_CREATED', '{
    "and": [
      {
        "op": "gt",
        "field": "amountCent",
        "value": 5000000
      },
      {
        "op": "neq",
        "field": "documentStatus",
        "value": "IN_PROCESS"
      }
    ]
  }', 'START_FLOW', '{
    "flowModelKey": "leave_multi",
