VALUES (2055998717093605378, 1, 1, 'ecde7d74-0f1a-4103-aed1-5f7a3402b1d1', 2055868122951540700, '用户活跃度监控大屏', 1,
        '用户管理', 2054373853659234305, 'DeepSeek', 'deepseek-v4-pro', 'dark', 1920, 1080,
