        <di:waypoint x="565" y="280" />
      </bpmndi:BPMNEdge>
      <bpmndi:BPMNEdge id="flow_hr_to_decision_di" bpmnElement="flow_hr_to_decision">
        <di:waypoint x="640" y="320" />
        <di:waypoint x="700" y="320" />
