<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL" xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI" xmlns:dc="http://www.omg.org/spec/DD/20100524/DC" xmlns:di="http://www.omg.org/spec/DD/20100524/DI" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:flowable="http://flowable.org/bpmn" targetNamespace="http://flowable.org/processdef">
  <bpmn:process id="powerstop" name="停电审核" isExecutable="true" flowable:initiator="initiator">
    <bpmn:startEvent id="StartEvent_1" name="开始" />
    <bpmn:sequenceFlow id="Flow_1" sourceRef="StartEvent_1" targetRef="Task_Apply" />
    <bpmn:userTask id="Task_Apply" name="车间申请" flowable:assignee="${initiator}" flowable:formKey="applyForm" flowable:priority="50">
      <bpmn:extensionElements />
      <bpmn:multiInstanceLoopCharacteristics isSequential="true">
        <bpmn:loopCardinality xsi:type="bpmn:tFormalExpression">${nrOfInstances}</bpmn:loopCardinality>
        <bpmn:completionCondition xsi:type="bpmn:tFormalExpression">${nrOfCompletedInstances == nrOfInstances}</bpmn:completionCondition>
      </bpmn:multiInstanceLoopCharacteristics>
    </bpmn:userTask>
    <bpmn:sequenceFlow id="Flow_2" sourceRef="Task_Apply" targetRef="Task_BranchApprove" />
    <bpmn:userTask id="Task_BranchApprove" name="分公司审批" flowable:assignee="${flowSpelService.findDeptManager(execution.getVariable(&#34;deptId&#34;))}" flowable:formKey="approveForm" flowable:priority="50" flowable:assigneeType="spel">
      <bpmn:extensionElements />
    </bpmn:userTask>
    <bpmn:sequenceFlow id="Flow_3" sourceRef="Task_BranchApprove" targetRef="Gateway_Approve" />
    <bpmn:exclusiveGateway id="Gateway_Approve" name="审批结果" />
    <bpmn:sequenceFlow id="Flow_4" sourceRef="Gateway_Approve" targetRef="Task_PowerApprove">
      <bpmn:conditionExpression xsi:type="bpmn:tFormalExpression">${approved}</bpmn:conditionExpression>
    </bpmn:sequenceFlow>
    <bpmn:sequenceFlow id="Flow_5" sourceRef="Gateway_Approve" targetRef="EndEvent_Reject">
      <bpmn:conditionExpression xsi:type="bpmn:tFormalExpression">${!approved}</bpmn:conditionExpression>
    </bpmn:sequenceFlow>
    <bpmn:userTask id="Task_PowerApprove" name="动力部审批" flowable:assignee="${flowSpelService.findUsersByRole(&#34;power_manager&#34;)}" flowable:formKey="approveForm" flowable:assigneeType="spel" />
    <bpmn:sequenceFlow id="Flow_6" sourceRef="Task_PowerApprove" targetRef="Task_DispatchPlan" />
    <bpmn:userTask id="Task_DispatchPlan" name="调度室计划" flowable:assignee="${flowSpelService.findUsersByRole(&#34;dispatch_office&#34;)}" flowable:formKey="planForm" flowable:assigneeType="spel">
      <bpmn:extensionElements />
    </bpmn:userTask>
    <bpmn:sequenceFlow id="Flow_7" sourceRef="Task_DispatchPlan" targetRef="Task_Operation" />
    <bpmn:userTask id="Task_Operation" name="操作队执行" flowable:assignee="${flowSpelService.findUsersByRole(&#34;operation_team&#34;)}" flowable:formKey="executeForm" flowable:assigneeType="spel">
      <bpmn:extensionElements />
    </bpmn:userTask>
    <bpmn:sequenceFlow id="Flow_8" sourceRef="Task_Operation" targetRef="ServiceTask_Notify" />
    <bpmn:serviceTask id="ServiceTask_Notify" name="通知干系人" flowable:class="org.flowable.engine.delegate.JavaDelegate" />
    <bpmn:sequenceFlow id="Flow_9" sourceRef="ServiceTask_Notify" targetRef="EndEvent_1" />
    <bpmn:endEvent id="EndEvent_1" name="结束" />
    <bpmn:endEvent id="EndEvent_Reject" name="拒绝结束" />
